q "INSERT INTO public.customer_requirements(id,requirement_number,opportunity_id,customer_id,title,status,current_revision) VALUES ('aaabd18c-5885-45de-9e0e-da70d4ec491f','CUSTOMER-2026-0003','0f965acc-5f00-4e3d-9000-9176d739a38c','a2f299d4-f8ba-4c5c-8dcf-5437bb21166e','testcust','draft',1),('36cdc159-57c7-4568-a1b0-ec481f5d3d93','CUSTOMER-2026-0004','0f965acc-5f00-4e3d-9000-9176d739a38c','a2f299d4-f8ba-4c5c-8dcf-5437bb21166e','testcust','draft',1),('6aa2fc2f-eb75-48c2-a9de-d13008cf1c5c','CUSTOMER-2026-0005','0f965acc-5f00-4e3d-9000-9176d739a38c','a2f299d4-f8ba-4c5c-8dcf-5437bb21166e','testcust','draft',1),('2db48440-5424-4e5e-bb5b-01f203a7662f','CUSTOMER-2026-0006','0f965acc-5f00-4e3d-9000-9176d739a38c','a2f299d4-f8ba-4c5c-8dcf-5437bb21166e','testcust','draft',1),('e829dd82-381d-42ab-a808-62979e9156f4','CUSTOMER-2026-0007','0f965acc-5f00-4e3d-9000-9176d739a38c','a2f299d4-f8ba-4c5c-8dcf-5437bb21166e','testcust','draft',1);"
