e4ec3-b3da-4437-aa5f-b5d0b4469d30'),('7c47d3cb-3102-4b2e-9ffc-ea61044f7bbe','e829dd82-381d-42ab-a808-62979e9156f4','sales','customer_requirement','created','Created requirement: CUSTOMER-2026-0007','e96e4ec3-b3da-4437-aa5f-b5d0b4469d30');"

# Writer-first: an unmodified direct child-table writer takes no archive advisory
# lock. It commits first; the archive sees the new lineage and rolls back fully.
psql "${psql_args[@]}" -Atqc "INSERT INTO public.sales_opportunity_structured_docx_assignments(id,opportunity_id) VALUES ('00000000-0000-4000-8000-000000000031','104fb9e2-7f83-40f9-a295-64b37aa8c7ee');"
archive_status=0
PGOPTIONS="-c request.jwt.claim.sub=00000000-0000-4000-8000-000000000001" psql "${psql_args[@]}" -Atqc "SELECT * FROM public.archive_reviewed_sales_samples('$roots'::jsonb,'writer first downstream lineage','00000000-0000-4000-8000-000000000032');" >"$work_dir/archive-writer-first.out" 2>"$work_dir/archive-writer-first.err" || archive_status=$?
[[ $archive_status -ne 0 ]] || { echo 'ASSERT_FAIL writer-first downstream lineage unexpectedly archived roots' >&2; exit 1; }
grep -Eq 'Archive is blocked by a live business dependency' "$work_dir/archive-writer-first.err" || { cat "$work_dir/archive-writer-first.err" >&2; exit 1; }
assert_eq "$(q "SELECT count(*) FROM public.sales_opportunities WHERE archived_at IS NOT NULL")" 0 'writer race leaves opportunity roots active'
assert_eq "$(q "SELECT count(*) FROM public.customer_requirements WHERE archived_at IS NOT NULL")" 0 'writer race leaves requirement roots active'
assert_eq "$(q "SELECT count(*) FROM public.sales_sample_archive_manifests")" 0 'writer race rolls back manifest'
assert_eq "$(q "SELECT count(*) FROM public.sales_sample_archive_manifest_items")" 0 'writer race rolls back manifest items'
assert_eq "$(q "SELECT count(*) FROM public.sales_sample_archive_audit_events")" 0 'writer race writes no audit'
assert_eq "$(q "SELECT count(*) FROM public.sales_opportunity_structured_docx_assignments WHERE id='00000000-0000-4000-8000-000000000031'")" 1 'writer committed a new downstream lineage record'
psql "${psql_args[@]}" -Atqc "DELETE FROM public.sales_opportunity_structured_docx_assignments WHERE id='00000000-0000-4000-8000-000000000031';"

# Archive-first: hold the candidate opportunity row FOR UPDATE without the
# archive advisory lock, then run the unmodified writer. Its trigger asks for a
# KEY SHARE lock, waits for the archive-side root state, and rejects after the
# archive commits. No writer-side archive-lock cooperation is involved.
psql "${psql_args[@]}" -Atqc "BEGIN; SELECT 1 FROM public.sales_opportunities WHERE id='104fb9e2-7f83-40f9-a295-64b37aa8c7ee' FOR UPDATE; SELECT pg_sleep(1.1); UPDATE public.sales_opportunities SET archived_at=now() WHERE id='104fb9e2-7f83-40f9-a295-64b37aa8c7ee'; COMMIT;" >"$work_dir/archive-first.out" 2>"$work_dir/archive-first.err" & archive_pid=$!
sleep 0.2
writer_status=0
psql "${psql_args[@]}" -Atqc "INSERT INTO public.sales_opportunity_structured_docx_assignments(id,opportunity_id) VALUES ('00000000-0000-4000-8000-000000000033','104fb9e2-7f83-40f9-a295-64b37aa8c7ee');" >"$work_dir/writer-archive-first.out" 2>"$work_dir/writer-archive-first.err" || writer_status=$?
wait "$archive_pid"
[[ $writer_status -ne 0 ]] || { echo 'ASSERT_FAIL archive-first writer unexpectedly created lineage' >&2; exit 1; }
grep -Eq 'Archived opportunity cannot receive downstream lineage' "$work_dir/writer-archive-first.err" || { cat "$work_dir/writer-archive-first.err" >&2; exit 1; }
assert_eq "$(q "SELECT count(*) FROM public.sales_opportunity_structured_docx_assignments WHERE id='00000000-0000-4000-8000-000000000033'")" 0 'archive-first rejects unmodified downstream writer'
assert_eq "$(q "SELECT count(*) FROM public.sales_sample_archive_manifests")" 0 'archive-first test creates no manifest'
assert_eq "$(q "SELECT count(*) FROM public.sales_sample_archive_audit_events")" 0 'archive-first test creates no audit'
printf 'UNMODIFIED_WRITER_FIRST_ARCHIVE_ATOMIC_REJECT_PASS=true\n'
printf 'UNMODIFIED_WRITER_ARCHIVE_FIRST_REJECT_PASS=true\n'
printf 'SALES_SAMPLE_ARCHIVE_RESTORE_LOCAL_CONCURRENCY_ACCEPTANCE_PASS=true\n'